{
  "passageId": "blockchain-features",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "블록체인 기술의 기본 정의에 새 블록의 처리 절차를 덧붙여 같은 기술을 더 자세히 설명한다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "새 블록의 전파와 검증 다음에 연결 여부를 결정하는 승인이 진행되는 단계적 순서이다."
    },
    {
      "id": "R3",
      "type": "PROCESS",
      "otherName": "",
      "reason": "승인 단계의 결과를 바탕으로 블록 연결과 저장이라는 다음 단계가 진행된다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "작업증명은 승인 과정에 사용되는 합의 알고리즘을 구체적인 사례로 보여 준다."
    },
    {
      "id": "R5",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "데이터 저장 속도라는 성능의 의미를 단위 시간당 저장량이라는 계산 표현으로 나타낸다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "승인에 사용되는 합의 알고리즘의 빠른 처리 속도가 실제 승인 시간의 단축으로 이어진다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "성능을 데이터 저장 속도로 정의했으므로 승인 시간이 짧다는 사실이 성능이 높다는 판단을 뒷받침한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "승인에 사용되는 합의 알고리즘을 공개형과 비공개형의 속도 차이로 더 자세히 설명한다."
    },
    {
      "id": "R9",
      "type": "PROCESS",
      "otherName": "",
      "reason": "데이터 변경으로 연결이 끊어진 뒤 재연결을 위해 승인 절차를 거쳐야 한다는 처리 순서이다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "끊어진 모든 블록의 재연결에 승인이 필요하다는 사실을 근거로 연결 복구가 어렵다고 설명한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "변경으로 끊어진 연결을 복구하기 어렵다는 사실이 연결을 유지한 데이터 변경도 어렵다는 설명을 뒷받침한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "무결성의 정의에 비추어 데이터 변경이 어렵다는 사실로부터 무결성이 높다는 판단을 도출한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "원래 데이터의 복원에는 승인이 필요하지 않다는 사실을 근거로 복원이 용이하다고 판단한다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "무단 변경 후 재연결과 삭제된 원래 데이터의 복원을 승인 필요 여부와 복구 난이도라는 같은 기준에서 비교한다."
    },
    {
      "id": "R15",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "블록 연결에는 승인이 필요하다는 일반 절차를 변경으로 끊어진 블록의 재연결 사례에 적용한다."
    },
    {
      "id": "R16",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "무결성으로 정의된 무단 변경의 어려움이 보안성을 구성하는 한 요소로 포함된다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노드가 이중 포함 여부를 검증한다는 작동 사실이 이중 포함이 어렵다는 보안성 설명을 뒷받침한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 노드가 승인에 참여한다는 작동 방식은 탈중앙성의 다수 노드 참여라는 성질을 구체적으로 보여 준다."
    },
    {
      "id": "R19",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "승인 시간이 짧아지면 보안성이 낮아진다는 일반 원리를 승인 시간이 짧은 비공개형의 사례에 연결한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노드 증가가 성능 저하를 일으킨다는 사실을 바탕으로 높은 확장성이 갖추어야 할 성능 유지 수준을 설명한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노드 제한으로 성능 저하를 막을 수 있다는 효과가 확장성 확보에 그 방법을 사용하는 이유로 제시된다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확장성을 높이기 위한 노드 수 제한이 보안성 저하로 이어지는 특성 간 상충 관계이다."
    },
    {
      "id": "R23",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확장성을 높이기 위한 노드 수 제한이 탈중앙성 저하로 이어지는 특성 간 상충 관계이다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "비공개형의 노드 수 제한은 확장성을 높이는 데 사용되는 노드 제한 방법의 구체적인 사례이다."
    },
    {
      "id": "R25",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "데이터 저장 속도로 정의된 성능의 충족 수준이 확장성을 구성하는 요건 가운데 하나로 제시된다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세 특성을 함께 높일 방법이 없다는 기술적 한계가 실제 대규모 채택을 가로막는 원인으로 제시된다."
    }
  ]
}

